decree_promote_social_mobility = {
	texture = "gfx/interface/icons/decree/decree_promote_social_mobility.dds"

	state_trigger = {
		NOT = {
			AND = {
				owner ?= {
					OR = {
						has_law_or_variant = law_type:law_hindu_caste_enforced
						has_law_or_variant = law_type:law_hindu_caste_codified
					}
				}
				religion_percent_state = {
					target = rel:hindu
					value >= 0.3
				}
			}
		}
	}

	modifier = {
		state_education_access_add = 0.25
		state_pop_qualifications_mult = 0.25
	}

	cost = 100

	ai_weight = {
		value = 0
		if = {
			limit = {
				scope:country.total_population > 0
			}
			add = {
				value = 1
				subtract = literacy_rate
				multiply = 100
			}
			multiply = {
				value = state_population
				divide = scope:country.total_population
				multiply = 20
				min = 0
				max = 2
			}
		}
		if = {
			limit = {
				scope:country = {
					OR = {
						has_strategy = ai_strategy_reactionary_agenda
						has_strategy = ai_strategy_conservative_agenda
						has_strategy = ai_strategy_maintain_mandate_of_heaven
					}
				}
			}
			multiply = 0.5
		}
		if = {
			limit = {
				scope:country = {
					OR = {
						has_strategy = ai_strategy_progressive_agenda
						has_strategy = ai_strategy_egalitarian_agenda
					}
				}
			}
			multiply = 1.5
		}
		if = {
			limit = {
				is_incorporated = no
			}
			multiply = 0.25
		}
		if = {
			limit = {
				is_capital = yes
			}
			multiply = 2
		}

		# Content overrides
		if = {
			limit = {
				scope:country = {
					has_journal_entry = je_lands_of_anarchy
				}
				is_capital = yes
			}
			add = 1000
		}
		if = {
			limit = {
				scope:country = { has_journal_entry = je_hawaii }
			}
			add = 1000
		}
		if = {
			limit = {
				scope:country = { has_journal_entry = je_portugal_regeneration_institutions }
				literacy_rate < 0.5
			}
			add = 500
		}
	}
}

decree_promote_national_values = {
	texture = "gfx/interface/icons/decree/decree_promote_national_values.dds"
	unlocking_technologies = {
		nationalism
	}

	country_trigger = {
		NOT = { has_law_or_variant = law_type:law_multicultural }
	}

	modifier = {
		state_assimilation_mult = 0.5
		state_conversion_mult = 0.5
		state_allow_assimilation_in_homeland_bool = yes
		state_allow_assimilation_without_presence_bool = yes
		state_allow_conversion_without_presence_bool = yes
		state_radicalism_increases_violent_hostility_mult = 0.5
		state_radicalism_increases_cultural_erasure_mult = 0.4
		state_radicalism_increases_open_prejudice_mult = 0.3
	}
	cost = 100

	ai_weight = {
		value = 0

		if = {
			limit = {
				scope:country = {
					NOR = {
						has_law_or_variant = law_type:law_multicultural
						has_law_or_variant = law_type:law_subjecthood
					}
				}
				primary_cultures_percent_state = {
					target_country = owner
					value <= 0.9
				}
			}

			if = { # Colonies
				limit = {
					scope:country = {
						is_not_in_geographic_region = geographic_region_europe
						any_primary_culture = {
							has_discrimination_trait_group = heritage_group_european
						}
						NOR = {
							has_government_type = gov_chartered_company
							c:BIC ?= this
							c:DEI ?= this
						}
					}
				}
				add = 300
			}
			else_if = {
				limit = {
					scope:country = {
						OR = {
							has_strategy = ai_strategy_reactionary_agenda
							has_strategy = ai_strategy_conservative_agenda
						}
					}
				}
				add = 100
			}
			else_if = {
				limit = {
					scope:country = {
						has_strategy = ai_strategy_nationalist_agenda
					}
				}
				add = 200
			}


			if = {
				limit = {
					primary_cultures_percent_state = {
						target_country = owner
						value <= 0.1
					}
				}
				multiply = 5.0
			}
			else_if = {
				limit = {
					primary_cultures_percent_state = {
						target_country = owner
						value <= 0.3
					}
				}
				multiply = 3.0
			}
			else_if = {
				limit = {
					primary_cultures_percent_state = {
						target_country = owner
						value <= 0.5
					}
				}
				multiply = 2.0
			}

			if = {
				limit = {
					is_homeland_of_country_cultures = scope:country
				}
				multiply = 5.0
			}
		}

		if = {
			limit = {
				OR = {
					NOT = { scope:country = { has_law_or_variant = law_type:law_total_separation } }
					AND = {
						scope:country = { is_not_in_geographic_region = geographic_region_africa }
						is_in_geographic_region = geographic_region_africa
					}
				}
				religion_percent_state = {
					target = scope:country.religion
					value <= 0.9
				}
			}

			if = {
				limit = {
					scope:country = {
						has_strategy = ai_strategy_conservative_agenda
					}
				}
				add = 50
			}
			else_if = {
				limit = {
					scope:country = {
						has_strategy = ai_strategy_reactionary_agenda
					}
				}
				add = 100
			}

			if = {
				limit = {
					scope:country = {
						OR = {
							has_law_or_variant = law_type:law_state_religion
							has_law_or_variant = law_type:law_state_atheism
						}
					}
				}
				add = 50
			}

			if = {
				limit = {
					religion_percent_state = {
						target = scope:country.religion
						value <= 0.1
					}
				}
				multiply = 5.0
			}
			else_if = {
				limit = {
					religion_percent_state = {
						target = scope:country.religion
						value <= 0.3
					}
				}
				multiply = 3.0
			}
			else_if = {
				limit = {
					religion_percent_state = {
						target = scope:country.religion
						value <= 0.5
					}
				}
				multiply = 2.0
			}
		}

		if = {
			limit = {
				state_population < 100000
			}
			multiply = 0
		}
		else_if = {
			limit = {
				state_population > 300000
			}
			multiply = 2.0
		}
		else_if = {
			limit = {
				scope:country = {
					OR = {
						has_law = law_type:law_cultural_exclusion
						has_law = law_type:law_freedom_of_conscience
					}
				}
			}
			multiply = 0.5
		}
		else_if = {
			limit = {
				scope:country = {
					OR = {
						has_law = law_type:law_multicultural
						has_law = law_type:law_total_separation
					}
				}
			}
			multiply = 0.1
		}

		if = { # Deliberately placed here since we want the AI to ignore laws for this
			limit = {
				scope:country = {
					has_journal_entry = je_south_american_national_identity
				}
			}
			add = 500
		}
		if = {
			limit = {
				scope:country = {
					has_journal_entry = je_vernacular_policy
					has_variable = chose_assimilation_var
				}
				is_homeland_of_country_cultures = scope:country
			}
			add = 1000
		}
		if = {
			limit = {
				scope:country = {
					has_journal_entry = je_colonize_korea
				}
				is_in_geographic_region = geographic_region_korea
			}
			add = 500
		}

		# For Japanese religion Journal Entry
		# If Shinbutsu Bunri is active and the Taikyo Proclamation has been made
		# Only pursue this aggressively with a pious ruler or Devout in government
		if = {
			limit = {
				scope:country = {
					has_journal_entry = je_shinbutsu_bunri
					country_has_state_religion = rel:shinto
					OR = {
						has_ruling_interest_group = ig_devout
						ruler = { has_ideology = ideology:ideology_pious }
					}
				}
			}
			add = 500
		}

		if = {
			limit = {
				primary_cultures_percent_state = {
					target_country = owner
					value > 0.9
				}
				religion_percent_state = {
					target = scope:country.religion
					value > 0.9
				}
			}
			multiply = 0
		}
		else_if = {
			limit = {
				primary_cultures_percent_state = {
					target_country = owner
					value > 0.5
				}
				religion_percent_state = {
					target = scope:country.religion
					value > 0.5
				}
			}
			multiply = 0.5
		}
	}
}

